('Paid Social Media Marketing Intern','paid-social-media-marketing-intern','marketing','social_media','Remote / NYC','internship','Paid internship','Create short-form content and help TheOutHaven grow local discovery.', 'open','public',true,'paid',true,true,false,8,15,12,'Learn content planning, social analytics, brand research, and local marketing operations.','reviewed'),
('Social Media Intern — Educational / College Credit','social-media-intern-educational-college-credit','marketing','social_media','Remote / NYC','internship','Educational / College Credit','Educational social media internship for school-credit or structured learning.', 'open','public',true,'college_credit',false,true,true,6,12,12,'Learn marketing, content strategy, social planning, research, and startup operations.','pending_review'),
('Marketing Intern — Paid','marketing-intern-paid','marketing','content','Remote','internship','Paid internship','Support campaigns, research, and community marketing.', 'open','public',true,'paid',true,true,false,8,15,12,'Learn campaign planning, local audience research, and marketing execution.','reviewed'),
('Marketing Intern — Educational / College Credit','marketing-intern-educational-college-credit','marketing','content','Remote','internship','Educational / College Credit','Structured educational marketing internship with school-credit support.', 'open','public',true,'college_credit',false,true,true,6,12,12,'Learn marketing operations, campaign planning, audience research, and reporting.','pending_review'),
('Campus Ambassador','campus-ambassador','campus','ambassador','Campus / Remote','part_time','Paid or campus program track','Represent TheOutHaven on campus and help students discover better outings.', 'open','public',true,'campus_ambassador',true,true,false,5,10,12,'Learn campus outreach, partnerships, and community growth.','reviewed'),
('Influencer Outreach Intern','influencer-outreach-intern','marketing','influencer_outreach','Remote','internship','Paid internship','Research creators and support outreach for local discovery campaigns.', 'open','public',true,'paid',true,true,false,8,12,12,'Learn influencer research, outreach operations, and campaign tracking.','reviewed'),
('Content Creator Intern','content-creator-intern','creator','content','Remote / Local','internship','Paid or creator program track','Create local outing content concepts and social media assets.', 'open','public',true,'creator_program',true,true,false,5,12,12,'Learn creator strategy, local content production, and content testing.','reviewed'),
('Experience Team Associate','experience-team-associate','experience',null,'Remote','part_time','Part-time compensation shared during hiring','Help users and partners have smooth TheOutHaven experiences.', 'draft','public',false,null,true,false,false,null,null,null,null,'not_required'),
('Partner Ambassador','partner-ambassador','partnerships','ambassador','Remote / Local','contract','Commission / contract details shared during hiring','Support partner outreach and onboarding for local businesses.', 'draft','public',false,null,true,false,false,null,null,null,null,'not_required')
on conflict (slug) do nothing;
insert into public.career_job_questions (job_id, question_label, required, sort_order)
select j.id, q.label, q.required, q.ord from public.career_jobs j cross join (values
('Which platforms do you use most?', true, 10),('Do you have experience creating content?', true, 20),('What type of content are you most interested in?', false, 30),('Upload or link examples of content you created.', false, 40),('Are you comfortable being on camera?', false, 50),('Are you comfortable visiting local businesses or events?', false, 60),('What areas can you cover?', false, 70),('Are you applying for paid internship, unpaid educational internship, college credit internship, or not sure?', true, 80),('Is this connected to a school, program, or college credit requirement?', false, 90)) as q(label,required,ord)
where j.department in ('marketing','campus','creator') on conflict do nothing;
